\set ON_ERROR_STOP on
create extension if not exists pgcrypto;
create schema if not exists auth;
create schema if not exists private;
do $$ begin if not exists(select 1 from pg_roles where rolname='anon') then create role anon nologin; end if; if not exists(select 1 from pg_roles where rolname='authenticated') then create role authenticated nologin; end if; end $$;
grant usage on schema public,private,auth to authenticated;
grant usage on schema public to anon;
create table if not exists public.profiles(id uuid primary key,email text,full_name text);
create table if not exists public.organizations(id uuid primary key,owner_user_id uuid not null references public.profiles(id),name text not null,status text not null default 'active');
create table if not exists public.licenses(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),user_id uuid not null references public.profiles(id),plan text not null default 'lifetime',status text not null default 'active',modules text[] not null default array['requests_workflow']::text[],ends_at date);
create table if not exists public.organization_members(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),user_id uuid not null references public.profiles(id),status text not null default 'active',is_owner boolean not null default false,position_title text,created_at timestamptz not null default now(),unique(organization_id,user_id));
create table if not exists public.member_module_permissions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),member_id uuid not null references public.organization_members(id),module_key text not null,capabilities text[] not null default array['read']::text[]);
create table if not exists public.organization_roles(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),role_key text not null,title text not null,active boolean not null default true);
create table if not exists public.organization_role_permissions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),role_id uuid not null references public.organization_roles(id),module_key text not null,capabilities text[] not null default array['read']::text[]);
create table if not exists public.organization_member_roles(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),member_id uuid not null references public.organization_members(id),role_id uuid not null references public.organization_roles(id),active boolean not null default true);
create table if not exists public.organization_audit(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),actor_user_id uuid references public.profiles(id),action text not null,entity_type text not null,entity_id text,before_data jsonb,after_data jsonb,created_at timestamptz not null default now());
insert into public.profiles(id,email,full_name) values('11111111-1111-1111-1111-111111111111','owner@example.test','Owner') on conflict do nothing;
insert into public.organizations(id,owner_user_id,name) values('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa','11111111-1111-1111-1111-111111111111','D1 Test Org') on conflict do nothing;
insert into public.organization_members(organization_id,user_id,status,is_owner) values('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa','11111111-1111-1111-1111-111111111111','active',true) on conflict do nothing;
insert into public.licenses(organization_id,user_id,plan,status,modules) select 'aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa','11111111-1111-1111-1111-111111111111','lifetime','active',array['requests_workflow']::text[] where not exists(select 1 from public.licenses where organization_id='aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa');
create or replace function auth.uid() returns uuid language sql stable as $$ select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $$;
create or replace function private.current_organization_ids() returns setof uuid language sql stable security definer set search_path='' as $$ select nullif(current_setting('request.jwt.claim.org',true),'')::uuid where coalesce(current_setting('request.jwt.claim.member_active',true),'true')='true' $$;
create or replace function private.organization_has_module_entitlement(p_organization_id uuid,p_module_key text,p_require_active boolean default false) returns boolean language sql stable security definer set search_path='' as $$ select coalesce(current_setting('request.jwt.claim.entitled',true),'true')='true' and p_organization_id='aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa'::uuid and p_module_key='requests_workflow' $$;
create or replace function private.has_org_capability(p_organization_id uuid,p_module_key text,p_capability text) returns boolean language sql stable security definer set search_path='' as $$ select p_organization_id='aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa'::uuid and p_module_key='requests_workflow' and p_capability=any(string_to_array(coalesce(nullif(current_setting('request.jwt.claim.capabilities',true),''),'read,configure,create,edit,approve'),',')) $$;
revoke all on function private.current_organization_ids() from public,anon;revoke all on function private.organization_has_module_entitlement(uuid,text,boolean) from public,anon;revoke all on function private.has_org_capability(uuid,text,text) from public,anon;grant execute on function private.current_organization_ids() to authenticated;grant execute on function private.organization_has_module_entitlement(uuid,text,boolean) to authenticated;grant execute on function private.has_org_capability(uuid,text,text) to authenticated;
grant select on public.profiles,public.organizations,public.organization_members,public.member_module_permissions,public.organization_roles,public.organization_role_permissions,public.organization_member_roles,public.organization_audit to authenticated;
